package itda.medicalsupport.dto;
import itda.medicalsupport.domain.*; import java.time.Instant; import java.util.List;
public record MedicalSupportProgramResponse(Long programId,String programName,MedicalSupportRegionScope regionScope,String regionCode,String region,int programYear,String summary,String supportAmount,String applicationPeriod,MedicalSupportProgramStatus status,MedicalSupportHospitalPolicy hospitalPolicy,String officialSource,Instant lastVerifiedAt,String supportTarget,String supportItems,String applicationMethod,String animalRegistrationCondition,String incomeWelfareCondition,String contact,List<Hospital> designatedHospitals) {
 public record Hospital(String name,String address,String phone,String sidoName,String sigunguName) {}
 public static MedicalSupportProgramResponse list(MedicalSupportProgram p){return new MedicalSupportProgramResponse(p.getId(),p.getProgramName(),p.getRegionScope(),p.getRegionCode(),region(p),p.getProgramYear(),p.getSummary(),p.getSupportAmount(),p.getApplicationPeriod(),p.getProgramStatus(),p.getHospitalPolicy(),p.getOfficialSourceUrl(),p.getLastVerifiedAt(),null,null,null,null,null,null,List.of());}
 public static MedicalSupportProgramResponse detail(MedicalSupportProgram p,MedicalSupportRevision r){List<Hospital> hs=r==null?List.of():r.getHospitals().stream().map(h->new Hospital(h.getName(),h.getAddress(),h.getPhone(),h.getSidoName(),h.getSigunguName())).toList(); return new MedicalSupportProgramResponse(p.getId(),p.getProgramName(),p.getRegionScope(),p.getRegionCode(),region(p),p.getProgramYear(),p.getSummary(),p.getSupportAmount(),p.getApplicationPeriod(),p.getProgramStatus(),p.getHospitalPolicy(),p.getOfficialSourceUrl(),p.getLastVerifiedAt(),p.getSupportTarget(),p.getSupportItems(),p.getApplicationMethod(),p.getAnimalRegistrationCondition(),p.getIncomeWelfareCondition(),p.getContact(),hs);} private static String region(MedicalSupportProgram p){return p.getRegionSigunguName()==null?p.getRegionSidoName():p.getRegionSidoName()+" "+p.getRegionSigunguName();}
}
